/*
 * A174383  Product of two consecutive odd numbers k, k+2 such that
 *          (k*(k+2))+-2 are primes.
 * https://oeis.org/A174383
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = product of two consecutive odd numbers k, k+2 such that
 *            k*(k+2)-2 and k*(k+2)+2 are both prime. The sequence is
 *            generated by searching for odd k in increasing order. Cache
 *            results to avoid recomputation
 * Range:     u8 n <= 3, u16 n <= 11, u32 n <= 612, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   isPrimeGeneric
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The necessary helper for primality testing is in the utils directory. */
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/isPrimeGeneric.h"

/* static state for memoisation */
static idx_t next_candidate_k = 3;          /* next odd k to test */
static seq_t *term_cache = NULL;            /* cache of a(n) values */
static size_t cached_terms = 0;             /* number of cached terms */
static size_t cache_capacity = 0;           /* allocated cache size */

/* Ensure the cache contains at least n terms (n >= 1). */
static void ensure_cache(idx_t n)
{
    /* grow cache if needed */
    if (cache_capacity < n) {
        size_t new_cap = cache_capacity ? cache_capacity << 1 : 64;
        while (new_cap < n) new_cap <<= 1;
        seq_t *new_cache = (seq_t *)realloc(term_cache, new_cap * sizeof(seq_t));
        term_cache = new_cache;
        cache_capacity = new_cap;
    }

    /* compute missing terms */
    while (cached_terms < n) {
        /* search for the next k such that both k*(k+2)-2 and +2 are prime */
        while (1) {
            seq_t prod = (seq_t)next_candidate_k * ((seq_t)next_candidate_k + 2);
            if (isPrimeGeneric(prod - 2) && isPrimeGeneric(prod + 2)) {
                term_cache[cached_terms++] = prod;
                next_candidate_k += 2;     /* move to next odd candidate */
                break;
            }
            next_candidate_k += 2;         /* skip to next odd k */
        }
    }
}

/* Public entry point for the sequence */
seq_t a(idx_t n)
{
    if (n < 1) return 0;   /* undefined for n == 0; return 0 */
    ensure_cache(n);
    return term_cache[n - 1];
}
